<script setup lang="ts">const shop=useShop(); const q=ref(''); const category=ref('All'); const gender=ref('All'); const size=ref('All'); const color=ref('All'); const sort=ref('featured'); const maxPrice=ref(200); const page=ref(1); const perPage=12; const allCategories=computed(()=>['All',...new Set(shop.products.map(p=>p.category))]); const filtered=computed(()=>{let list=[...shop.products];if(q.value)list=list.filter(p=>`${p.name} ${p.category} ${p.description}`.toLowerCase().includes(q.value.toLowerCase()));if(category.value!=='All')list=list.filter(p=>p.category===category.value);if(gender.value!=='All')list=list.filter(p=>p.gender===gender.value);if(size.value!=='All')list=list.filter(p=>p.sizes.includes(size.value));if(color.value!=='All')list=list.filter(p=>p.colors.includes(color.value));list=list.filter(p=>shop.price(p)<=maxPrice.value);if(sort.value==='price-low')list.sort((a,b)=>shop.price(a)-shop.price(b));if(sort.value==='price-high')list.sort((a,b)=>shop.price(b)-shop.price(a));if(sort.value==='newest')list.sort((a,b)=>Number(b.isNew)-Number(a.isNew));if(sort.value==='popular')list.sort((a,b)=>b.reviews-a.reviews);return list});const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage)));const visible=computed(()=>filtered.value.slice((page.value-1)*perPage,page.value*perPage));watch([q,category,gender,size,color,sort,maxPrice],()=>page.value=1);function clear(){q.value='';category.value='All';gender.value='All';size.value='All';color.value='All';sort.value='featured';maxPrice.value=200}const route=useRoute();onMounted(()=>{if(typeof route.query.q==='string')q.value=route.query.q})</script>
<template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-10 sm:py-14"><div class="mb-8 border-b border-gray-100 pb-8"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-brand">The collection</p><h1 class="mt-2 text-4xl font-semibold tracking-[-.06em] sm:text-5xl">Shop all pieces<span class="text-brand">.</span></h1><p class="mt-3 max-w-lg text-sm leading-6 text-gray-500">Good things for your everyday rotation. Find your fit, make it yours.</p></div><div class="grid gap-8 lg:grid-cols-[220px_1fr]"><aside class="space-y-5"><div><label class="mb-2 block text-xs font-bold uppercase tracking-wider">Search</label><input v-model="q" class="w-full rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none focus:border-brand" placeholder="Try 'shirt'..."></div><div><label class="mb-2 block text-xs font-bold uppercase tracking-wider">Collection</label><select v-model="category" class="w-full rounded-xl border border-gray-200 bg-white px-3 py-3 text-sm"><option v-for="c in allCategories" :key="c">{{ c }}</option></select></div><div><label class="mb-2 block text-xs font-bold uppercase tracking-wider">Style</label><select v-model="gender" class="w-full rounded-xl border border-gray-200 bg-white px-3 py-3 text-sm"><option>All</option><option>Women</option><option>Men</option><option>Accessories</option></select></div><div><label class="mb-2 block text-xs font-bold uppercase tracking-wider">Size</label><select v-model="size" class="w-full rounded-xl border border-gray-200 bg-white px-3 py-3 text-sm"><option>All</option><option v-for="s in ['XS','S','M','L','XL','30','32','34','36','38','39','40','41','42','43','One size']" :key="s">{{ s }}</option></select></div><div><label class="mb-2 block text-xs font-bold uppercase tracking-wider">Color</label><select v-model="color" class="w-full rounded-xl border border-gray-200 bg-white px-3 py-3 text-sm"><option>All</option><option v-for="c in ['Black','White','Cream','Grey','Blue','Navy','Sand','Olive','Brown','Tan','Silver','Gold','Pink','Camel','Natural','Ivory']" :key="c">{{ c }}</option></select></div><div><div class="mb-2 flex justify-between text-xs font-bold uppercase tracking-wider"><label>Max price</label><span>${{ maxPrice }}</span></div><input v-model.number="maxPrice" type="range" min="20" max="200" step="5" class="w-full accent-brand"></div><button class="w-full rounded-full border border-gray-200 px-4 py-3 text-xs font-bold uppercase tracking-wider transition hover:border-ink" @click="clear">Clear filters ↺</button></aside><section><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><p class="text-sm text-gray-500"><strong class="text-ink">{{ filtered.length }}</strong> pieces to explore</p><select v-model="sort" class="rounded-full border border-gray-200 bg-white px-4 py-2.5 text-xs"><option value="featured">Sort: Featured</option><option value="newest">Newest first</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="popular">Most popular</option></select></div><ProductGrid :products="visible"/><div v-if="pageCount>1" class="mt-10 flex items-center justify-center gap-3"><button class="rounded-full border px-4 py-2 text-sm disabled:opacity-30" :disabled="page===1" @click="page--">← Previous</button><span class="text-xs text-gray-500">Page {{ page }} of {{ pageCount }}</span><button class="rounded-full border px-4 py-2 text-sm disabled:opacity-30" :disabled="page===pageCount" @click="page++">Next →</button></div></section></div></div></template>
